import { Router } from "express";
import { z } from "zod";
import { countOpenIncidents, findHome, listHomes } from "../store.ts";

export const homesRouter = Router();

/** GET /api/homes — every home, with how many incidents are currently open. */
homesRouter.get("/", (_req, res) => {
  res.json({
    homes: listHomes().map((home) => ({ ...home, openIncidents: countOpenIncidents(home.id) })),
  });
});

const homeParams = z.object({ homeId: z.string().min(1) });

/** GET /api/homes/:homeId — one home. */
homesRouter.get("/:homeId", (req, res) => {
  const params = homeParams.safeParse(req.params);
  if (!params.success) {
    res.status(400).json({ error: "invalid_params", detail: params.error.issues });
    return;
  }

  const home = findHome(params.data.homeId);
  if (!home) {
    res.status(404).json({ error: "home_not_found", homeId: params.data.homeId });
    return;
  }
  res.json({ home: { ...home, openIncidents: countOpenIncidents(home.id) } });
});

import { Router } from "express";
import { z } from "zod";
import { findHome, listIncidents } from "../store.ts";

export const incidentsRouter = Router({ mergeParams: true });

const incidentParams = z.object({ homeId: z.string().min(1) });

const incidentQuery = z.object({
  state: z.enum(["open", "resolved"]).optional(),
});

/** GET /api/homes/:homeId/incidents — a home's incidents, newest first. */
incidentsRouter.get("/", (req, res) => {
  const params = incidentParams.safeParse(req.params);
  if (!params.success) {
    res.status(400).json({ error: "invalid_params", detail: params.error.issues });
    return;
  }

  const query = incidentQuery.safeParse(req.query);
  if (!query.success) {
    res.status(400).json({ error: "invalid_query", detail: query.error.issues });
    return;
  }

  const { homeId } = params.data;
  if (!findHome(homeId)) {
    res.status(404).json({ error: "home_not_found", homeId });
    return;
  }

  res.json({ incidents: listIncidents(homeId, query.data.state) });
});

/**
 * The data layer. Reads the fixture once at startup and keeps it in memory, so the service has
 * no database to set up. Writes stay in memory and are lost on restart.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export type Home = {
  id: string;
  name: string;
  address: string;
  timezone: string;
  devices: number;
};

export type IncidentKind = "noise" | "occupancy" | "offline";
export type IncidentStatus = "open" | "resolved";

export type Incident = {
  id: string;
  homeId: string;
  kind: IncidentKind;
  startedAt: string;
  endedAt: string | null;
  peakDb: number | null;
  status: IncidentStatus;
};

type Fixture = { homes: Home[]; incidents: Incident[] };

const dataFile = join(dirname(fileURLToPath(import.meta.url)), "../data/homes.json");
const fixture: Fixture = JSON.parse(readFileSync(dataFile, "utf8"));

const homes = [...fixture.homes];
const incidents = [...fixture.incidents];

export const listHomes = (): Home[] => [...homes];

export const findHome = (id: string): Home | undefined => homes.find((home) => home.id === id);

export function listIncidents(homeId: string, status?: IncidentStatus): Incident[] {
  return incidents
    .filter((incident) => incident.homeId === homeId)
    .filter((incident) => (status ? incident.status === status : true))
    .sort((a, b) => b.startedAt.localeCompare(a.startedAt));
}

export const countOpenIncidents = (homeId: string): number =>
  incidents.filter((incident) => incident.homeId === homeId && incident.status === "open").length;

