import express from "express";
import { homesRouter } from "./routes/homes.ts";
import { incidentsRouter } from "./routes/incidents.ts";

export function createApp() {
  const app = express();
  app.use(express.json());

  // The dev web app runs on another port.
  app.use((_req, res, next) => {
    res.setHeader("access-control-allow-origin", "*");
    res.setHeader("access-control-allow-headers", "content-type");
    next();
  });

  app.get("/api/health", (_req, res) => res.json({ ok: true }));
  app.use("/api/homes/:homeId/incidents", incidentsRouter);
  app.use("/api/homes", homesRouter);

  app.use((_req, res) => res.status(404).json({ error: "not_found" }));
  return app;
}

import type { Home } from "../api.ts";

type Props = {
  homes: Home[];
  selectedId: string | null;
  onSelect: (id: string) => void;
};

export function HomeList({ homes, selectedId, onSelect }: Props) {
  return (
    <nav className="panel" aria-label="Homes">
      <h2>Homes</h2>
      <ul className="homes">
        {homes.map((home) => (
          <li key={home.id}>
            <button
              type="button"
              className={home.id === selectedId ? "home selected" : "home"}
              aria-current={home.id === selectedId}
              onClick={() => onSelect(home.id)}
            >
              <span className="home-name">{home.name}</span>
              <span className="home-address">{home.address}</span>
              {home.openIncidents > 0 && (
                <span className="badge" title={`${home.openIncidents} open incidents`}>
                  {home.openIncidents}
                </span>
              )}
            </button>
          </li>
        ))}
      </ul>
    </nav>
  );
}

import { useEffect, useState } from "react";
import type { Home, Incident } from "../api.ts";
import { getIncidents } from "../api.ts";
import { formatPeak, formatStarted, kindLabel } from "../format.ts";

export function IncidentList({ home }: { home: Home }) {
  const [incidents, setIncidents] = useState<Incident[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setIncidents(null);
    setError(null);
    let current = true;
    getIncidents(home.id, "open").then(
      (rows) => { if (current) setIncidents(rows); },
      (reason: unknown) => { if (current) setError(String(reason)); },
    );
    return () => {
      current = false;
    };
  }, [home.id]);

  return (
    <section className="panel" aria-label={`Incidents for ${home.name}`}>
      <h2>{home.name}</h2>
      <p className="muted">
        {home.devices} device{home.devices === 1 ? "" : "s"} · {home.timezone}
      </p>

      {error && <p className="error">Could not load incidents: {error}</p>}
      {!incidents && !error && <p className="muted">Loading…</p>}
      {incidents?.length === 0 && <p className="muted">No open incidents.</p>}

      {incidents && incidents.length > 0 && (
        <ul className="incidents">
          {incidents.map((incident) => (
            <li key={incident.id} className={`incident ${incident.kind}`}>
              <span className="incident-kind">{kindLabel[incident.kind]}</span>
              <span className="incident-when">{formatStarted(incident.startedAt)}</span>
              <span className="incident-peak">{formatPeak(incident.peakDb)}</span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

/** Everything this app knows about the backend. */

const BASE = import.meta.env.VITE_API_URL ?? "http://localhost:3001";

export type Home = {
  id: string;
  name: string;
  address: string;
  timezone: string;
  devices: number;
  openIncidents: number;
};

export type IncidentKind = "noise" | "occupancy" | "offline";
export type IncidentStatus = "open" | "resolved";

export type Incident = {
  id: string;
  homeId: string;
  kind: IncidentKind;
  startedAt: string;
  endedAt: string | null;
  peakDb: number | null;
  status: IncidentStatus;
};

async function get<T>(path: string): Promise<T> {
  const res = await fetch(`${BASE}${path}`);
  if (!res.ok) throw new Error(`${path} returned ${res.status}`);
  // The response shape is trusted here, not validated. The backend's own tests are what hold it.
  return res.json() as Promise<T>;
}

export async function getHomes(): Promise<Home[]> {
  const body = await get<{ homes: Home[] }>("/api/homes");
  return body.homes;
}

export async function getIncidents(homeId: string, status?: IncidentStatus): Promise<Incident[]> {
  const query = status ? `?status=${status}` : "";
  const body = await get<{ incidents: Incident[] }>(`/api/homes/${homeId}/incidents${query}`);
  return body.incidents;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { z } from "zod";
import { createApp } from "../src/app.ts";

/** Start the app on a free port for one test and shut it down afterwards. */
async function withServer<T>(use: (base: string) => Promise<T>): Promise<T> {
  const server = createApp().listen(0);
  await new Promise((resolve) => server.once("listening", resolve));
  const address = server.address();
  if (address === null || typeof address === "string") throw new Error("server did not bind a port");
  try {
    return await use(`http://127.0.0.1:${address.port}`);
  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
}

/** `fetch`, with the body left as `unknown` so each test parses the shape it expects. */
async function get(url: string): Promise<{ status: number; body: unknown }> {
  const res = await fetch(url);
  return { status: res.status, body: await res.json() };
}

const homeSchema = z.object({
  id: z.string(),
  name: z.string(),
  address: z.string(),
  timezone: z.string(),
  devices: z.number(),
  openIncidents: z.number(),
});

const incidentSchema = z.object({
  id: z.string(),
  homeId: z.string(),
  kind: z.enum(["noise", "occupancy", "offline"]),
  startedAt: z.string(),
  endedAt: z.string().nullable(),
  peakDb: z.number().nullable(),
  status: z.enum(["open", "resolved"]),
});

const errorSchema = z.object({ error: z.string() });

test("GET /api/health", async () => {
  await withServer(async (base) => {
    const { status, body } = await get(`${base}/api/health`);
    assert.equal(status, 200);
    assert.deepEqual(body, { ok: true });
  });
});

test("GET /api/homes lists homes with their open incident count", async () => {
  await withServer(async (base) => {
    const { status, body } = await get(`${base}/api/homes`);
    assert.equal(status, 200);
    const { homes } = z.object({ homes: z.array(homeSchema) }).parse(body);
    assert.equal(homes.length, 4);
    assert.equal(homes.find((home) => home.id === "h-01")?.openIncidents, 2);
  });
});

